import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry matmul_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K,
    .param .u32 K_chunk
)
{
    .reg .u32 %r<30>;
    .reg .u64 %rd<30>;
    .reg .f32 %f<10>;
    .reg .pred %p<8>;
    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1, [M];
    ld.param.u32 %r2, [N];
    ld.param.u32 %r3, [K];
    ld.param.u32 %r4, [K_chunk];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    // row = blockIdx.y * blockDim.y + threadIdx.y
    mov.u32 %r5, %ctaid.y;
    mov.u32 %r6, %ntid.y;
    mov.u32 %r7, %tid.y;
    mad.lo.u32 %r8, %r5, %r6, %r7;
    // col = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32 %r9, %ctaid.x;
    mov.u32 %r10, %ntid.x;
    mov.u32 %r11, %tid.x;
    mad.lo.u32 %r12, %r9, %r10, %r11;
    setp.ge.u32 %p1, %r8, %r1;
    setp.ge.u32 %p2, %r12, %r2;
    or.pred %p3, %p1, %p2;
    @%p3 bra DONE;
    // Split-K range for this CTA (blockIdx.z)
    mov.u32 %r13, %ctaid.z;
    mul.lo.u32 %r14, %r13, %r4;      // k_start = blockIdx.z * K_chunk
    add.u32 %r15, %r14, %r4;         // tentative k_end
    setp.gt.u32 %p4, %r15, %r3;
    selp.b32 %r16, %r3, %r15, %p4;   // k_end = min(tentative, K)
    // A row pointer = A_ptr + row*K*4
    cvt.u64.u32 %rd4, %r8;
    cvt.u64.u32 %rd5, %r3;
    mul.lo.u64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.u64 %rd8, %rd1, %rd7;
    // B col pointer = B_ptr + col*4
    cvt.u64.u32 %rd9, %r12;
    shl.b64 %rd10, %rd9, 2;
    add.u64 %rd11, %rd2, %rd10;
    // N stride in bytes = N*4
    cvt.u64.u32 %rd12, %r2;
    shl.b64 %rd13, %rd12, 2;
    // advance B pointer to k_start row
    cvt.u64.u32 %rd20, %r14;
    mul.lo.u64 %rd21, %rd20, %rd13;
    add.u64 %rd11, %rd11, %rd21;
    mov.f32 %f1, 0f00000000;
    mov.u32 %r17, %r14;   // loop counter starts at k_start
LOOP_START:
    setp.ge.u32 %p5, %r17, %r16;
    @%p5 bra LOOP_END;
    cvt.u64.u32 %rd14, %r17;
    shl.b64 %rd15, %rd14, 2;
    add.u64 %rd16, %rd8, %rd15;
    ld.global.f32 %f2, [%rd16];
    ld.global.f32 %f3, [%rd11];
    fma.rn.f32 %f1, %f2, %f3, %f1;
    add.u64 %rd11, %rd11, %rd13;
    add.u32 %r17, %r17, 1;
    bra LOOP_START;
LOOP_END:
    cvt.u64.u32 %rd17, %r8;
    mul.lo.u64 %rd18, %rd17, %rd12;
    add.u64 %rd18, %rd18, %rd9;
    shl.b64 %rd19, %rd18, 2;
    add.u64 %rd19, %rd3, %rd19;
    atom.global.add.f32 %f4, [%rd19], %f1;
DONE:
    ret;
}
